<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {api} from '@/api';import {useAuthStore} from '@/stores/auth';import {Search,Clock,Coin,User} from '@element-plus/icons-vue';import {ElMessage} from 'element-plus';import {useRouter} from 'vue-router';
const auth=useAuthStore(),router=useRouter();const rows=ref<any[]>([]),total=ref(0),page=ref(1),keyword=ref(''),type=ref('');const types=[['','全部任务'],['PENETRATION','渗透测试'],['BUG_BOUNTY','漏洞挖掘'],['SECURITY_AUDIT','安全审计'],['RED_BLUE','红蓝对抗'],['CTF','CTF 挑战']];
async function load(){try{const d:any=await api.get('/tasks',{params:{page:page.value,size:9,keyword:keyword.value,type:type.value}});rows.value=d.records;total.value=d.total}catch{rows.value=[];total.value=0}}onMounted(load);watch(type,()=>{page.value=1;load()});async function apply(id:number){if(!auth.loggedIn){router.push('/login');return}try{await api.post('/task/apply',{taskId:id,message:'申请参与该授权安全测试任务'});ElMessage.success('申请已提交，任务已加入工作台')}catch(e:any){ElMessage.error(e.message)}}const money=(n:number)=>new Intl.NumberFormat('zh-CN').format(n);
</script>
<template><div class="page"><div class="page-head"><div><span class="eyebrow">Security mission marketplace</span><h1>白帽任务大厅</h1><p>只展示企业已授权的测试任务，申请前请确认范围与规则。</p></div><div class="search"><el-input v-model="keyword" placeholder="搜索任务名称或描述" @keyup.enter="load"><template #prefix><el-icon><Search/></el-icon></template></el-input><el-button type="primary" @click="load">检索</el-button></div></div><div class="filters"><button v-for="t in types" :key="t[0]" :class="{active:type===t[0]}" @click="type=t[0]">{{t[1]}}</button><span>{{total}} 个开放任务</span></div><div class="market-grid"><article v-for="t in rows" :key="t.id" class="mission panel"><div class="mission-top"><span class="task-no">{{t.taskNo}}</span><span class="state"><i></i>招募中</span></div><div class="mission-body"><div class="tags"><span class="tag">{{types.find(x=>x[0]===t.type)?.[1]||t.type}}</span><span>{{t.difficulty}}</span></div><h2>{{t.title}}</h2><p>{{t.description}}</p><div class="asset">授权资产：{{t.targetAssets}}</div></div><div class="facts"><div><Coin/><span>任务赏金<b>¥{{money(t.rewardAmount)}}</b></span></div><div><User/><span>人数上限<b>{{t.memberLimit}} 人</b></span></div><div><Clock/><span>截止日期<b>{{t.endDate}}</b></span></div></div><button class="apply" @click="apply(t.id)">申请参与 <span>→</span></button></article></div><div v-if="!rows.length" class="empty">暂无符合条件的任务</div><el-pagination v-if="total>9" v-model:current-page="page" :page-size="9" :total="total" layout="prev, pager, next" @current-change="load"/></div></template>
<style scoped>.search{display:flex;width:390px;gap:8px}.filters{display:flex;align-items:center;border-bottom:1px solid #1d2c3d;margin-bottom:20px;overflow:auto}.filters button{border:0;background:transparent;color:#788ba0;padding:12px 17px;white-space:nowrap;border-bottom:2px solid transparent;cursor:pointer}.filters button.active{color:#7de4fb;border-color:#39d5ff;background:#0b1825}.filters span{margin-left:auto;font:10px monospace;color:#5f7489}.market-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.mission{overflow:hidden}.mission-top{padding:11px 16px;border-bottom:1px solid #1d2c3d;display:flex;justify-content:space-between;font:10px monospace;color:#61768c}.state{color:#41dda2}.state i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#41dda2;margin-right:5px}.mission-body{padding:18px}.tags{display:flex;justify-content:space-between;color:#ffbf5b;font:10px monospace}.mission h2{font-size:16px;margin:17px 0 9px}.mission p{height:44px;overflow:hidden;color:#75889d;font-size:11px;line-height:1.8}.asset{font:10px monospace;color:#536b83;border-left:2px solid #29475e;padding-left:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.facts{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #1d2c3d}.facts>div{display:flex;align-items:center;gap:7px;padding:12px;border-right:1px solid #1d2c3d}.facts>div:last-child{border:0}.facts svg{width:14px;color:#5bc8e3}.facts span,.facts b{display:block;font-size:9px;color:#64798e}.facts b{color:#bacbdd;margin-top:4px}.apply{width:100%;border:0;border-top:1px solid #224156;background:#0c2130;color:#73ddf5;padding:12px;cursor:pointer}.apply:hover{background:#123247}.apply span{float:right}.el-pagination{justify-content:center;margin-top:25px}@media(max-width:1050px){.market-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.page-head{display:block}.search{width:100%;margin-top:18px}.market-grid{grid-template-columns:1fr}.filters span{display:none}}</style>
